'use client'

import * as React from 'react'
import { RadioGroup } from 'radix-ui'
import { Check, EditPencil, NavArrowLeft, NavArrowRight } from 'iconoir-react'
import { cn } from '@/lib/utils'
import { Button } from '@/registry/satin/ui/button'
import { Checkbox } from '@/registry/satin/ui/checkbox'
import { useSatinLabels } from '@/registry/satin/ui/labels'

/**
 * DecisionCard, 1:1 with the uiKit `DecisionCard` set (3096:1626) and its `decisionItem` rows
 * (3092:61608): one question an agent asks, its answers, and Skip / Continue.
 *
 * The card is 364 wide, bg/popover, border/default, radius-2xl, shadow-xs. The header is the
 * medium 14/20 title with an optional step navigator (24px icon buttons around "1/3"); the
 * footer is a tertiary Skip in text/muted and a primary Continue, 16px above and 12px below.
 *
 * - `radio` / `checkbox`: rows of 20px with 4px padding, hover bg action/secondary, 2px apart.
 * - `chips`: wrapping 28px pills 6px apart; selected ones take component/decision-chip: status/brand
 *   in Light, a brand edge and tint with a text/default label in Dark.
 * - `ranking`: 10px-radius rows with a grip, a rank dot (primary for #1) and the label. Drag to
 *   reorder, or Alt + Arrow keys; the dragged row lifts with border/strong and the md shadow.
 * - `draft`: the agent's text in a bubble (radius-2xl, 4px top-left); Rewrite makes it editable.
 * - `summary`: what the card collapses to once answered, with a Change action.
 *
 * Stepping between questions slides like a track: the old title and answers and the new ones sit
 * side by side, 24px apart, and move a whole card's width to the side (the new ones in from the
 * right going forward), the one leaving fading out; each part's box eases to the new height as
 * they go, clipped while it moves. All of it is 360 ms on cubic-bezier(0.22, 1, 0.36, 1). The
 * "1/3" count rolls its changed digit like an odometer (up going forward, down going back, 350
 * ms). The navigator and the footer stay put. Stepping again mid-slide carries on from where
 * things are. A part that reads the same on both steps (a title every step shares) stays still.
 * Under reduced motion nothing moves: the step just changes. Moving on with Continue or Skip
 * puts focus into the new question (its picked answer, or its first control); the step buttons
 * keep it. The card doesn't step by itself: move `step`, `title` and the answers from
 * `onContinue` and `onSkip`.
 *
 * For a step none of the types covers, pass `children`: they take the answers' place and move
 * with the step. `footer` takes Skip and Continue's place, in the same row. Other props, `ref`
 * included, go to the card's `div`.
 */

export type DecisionOption = {
  value: string
  label: string
  /** 14px icon, used by `chips`. */
  icon?: React.ReactNode
}

export type DecisionValue = string | string[]

export interface DecisionCardProps
  extends Omit<React.ComponentProps<'div'>, 'title' | 'defaultValue' | 'onChange'> {
  type?: 'radio' | 'checkbox' | 'chips' | 'ranking' | 'draft' | 'summary'
  title: string
  /** "1/3". Shows the step navigator. */
  step?: string
  onPreviousStep?: () => void
  onNextStep?: () => void
  /** A muted line under the title, e.g. "Select up to 5". */
  hint?: string
  options?: DecisionOption[]
  /**
   * radio: the chosen value. checkbox / chips: the chosen values. ranking: every value in order.
   * draft: the text. summary: the values to list.
   */
  value?: DecisionValue
  defaultValue?: DecisionValue
  onValueChange?: (value: DecisionValue) => void
  /** chips: how many can be picked. */
  max?: number
  /** draft: the bold first line of the draft, e.g. the subject. */
  draftTitle?: string
  onContinue?: (value: DecisionValue) => void
  onSkip?: () => void
  /** summary: reopens the question. */
  onEdit?: () => void
  /** draft: called when Rewrite is pressed, after the field becomes editable. */
  onRewrite?: () => void
  /** Defaults to the `continue` label, or `useReply` on a draft. */
  continueLabel?: string
  /** Defaults to the `skip` label. */
  skipLabel?: string
  /** The step navigator's previous button. Defaults to the `previousQuestion` label. */
  previousStepLabel?: string
  /** The step navigator's next button. Defaults to the `nextQuestion` label. */
  nextStepLabel?: string
  /** A body of your own, in place of the type's answers; it moves with the step. */
  children?: React.ReactNode
  /** Actions of your own, in place of Skip and Continue, in the footer row (not on a draft). */
  footer?: React.ReactNode
}

export function DecisionCard({
  className,
  type = 'radio',
  title,
  step,
  onPreviousStep,
  onNextStep,
  hint,
  options = [],
  value: valueProp,
  defaultValue,
  onValueChange,
  max,
  draftTitle,
  onContinue,
  onSkip,
  onEdit,
  onRewrite,
  continueLabel,
  skipLabel: skipLabelProp,
  previousStepLabel,
  nextStepLabel,
  children,
  footer,
  ref,
  ...props
}: DecisionCardProps) {
  const labels = useSatinLabels()
  const skipLabel = skipLabelProp ?? labels.skip
  const [inner, setInner] = React.useState<DecisionValue>(
    () => defaultValue ?? initialValue(type, options),
  )
  // A new question (another step or title) starts from its own default, not the last one's picks.
  const question = step ?? title
  const [innerFor, setInnerFor] = React.useState(question)
  if (innerFor !== question) {
    setInnerFor(question)
    setInner(defaultValue ?? initialValue(type, options))
  }
  const value = valueProp ?? inner
  const set = (next: DecisionValue) => {
    setInner(next)
    onValueChange?.(next)
  }
  const titleId = React.useId()
  const cardRef = React.useRef<HTMLDivElement>(null)
  const titleRef = React.useRef<HTMLDivElement>(null)
  const bodyRef = React.useRef<HTMLDivElement>(null)
  const footerRef = React.useRef<HTMLDivElement>(null)
  useStepSlide(question, step, cardRef, [titleRef, bodyRef])

  // Continue or Skip took the user to another question: focus goes into it (its picked answer,
  // or the first control), so the new question is read out and answered from there. From the
  // step buttons, focus stays on them. `inStep` remembers focus in the answers or the footer, for
  // when the step takes that control away (a draft's footer is its own) and focus falls to the page.
  const inStep = React.useRef(false)
  React.useEffect(() => {
    const card = cardRef.current
    if (!card) return
    const onFocusIn = (e: FocusEvent) => {
      inStep.current = !!(footerRef.current?.contains(e.target as Node) || bodyRef.current?.contains(e.target as Node))
    }
    // Leaving the card clears it, but not a control the step took away: browsers send focusout
    // for that too, so it waits until after the step's layout effects and checks the control is
    // still on the page.
    const onFocusOut = (e: FocusEvent) => {
      if (card.contains(e.relatedTarget as Node | null)) return
      const from = e.target as Node
      queueMicrotask(() => {
        if (from.isConnected) inStep.current = false
      })
    }
    card.addEventListener('focusin', onFocusIn)
    card.addEventListener('focusout', onFocusOut)
    return () => {
      card.removeEventListener('focusin', onFocusIn)
      card.removeEventListener('focusout', onFocusOut)
    }
  }, [])
  const shown = React.useRef(question)
  React.useLayoutEffect(() => {
    if (shown.current === question) return
    shown.current = question
    const active = document.activeElement
    const lost = !active || active === document.body
    if (!footerRef.current?.contains(active) && !(lost && inStep.current)) return
    const body = bodyRef.current
    const target =
      body?.querySelector<HTMLElement>('[role="radio"][aria-checked="true"]') ??
      [...(body?.querySelectorAll<HTMLElement>(TABBABLE) ?? [])].find((n) => n.getAttribute('role') !== 'radiogroup') ??
      body?.querySelector<HTMLElement>('[role="radio"]:not(:disabled)')
    target?.focus({ preventScroll: true })
  }, [question])

  const card = cn(
    'sa:flex sa:w-[364px] sa:max-w-full sa:flex-col sa:overflow-clip sa:rounded-2xl sa:border sa:border-border-default sa:bg-bg-popover',
    'sa:[box-shadow:0_1px_2px_0_var(--sa-effect-shadow-xs)]',
    className,
  )

  if (type === 'summary') {
    const values = asArray(value)
    const picked = values.map((v) => options.find((o) => o.value === v)?.label ?? v)
    return (
      <div ref={ref} data-slot="decision-card" data-type="summary" className={card} {...props}>
        <div className="sa:flex sa:items-center sa:gap-2.5 sa:py-2.5 sa:ps-3 sa:pe-2.5">
          <span className="sa:flex sa:size-6 sa:shrink-0 sa:items-center sa:justify-center sa:rounded-full sa:bg-action-primary-bg sa:text-action-primary-fg">
            <Check aria-hidden className="sa:size-icon-size-sm sa:[stroke-width:1.875]" />
          </span>
          <div className="sa:flex sa:min-w-0 sa:flex-1 sa:flex-col">
            <span className="sa:truncate sa:text-xs sa:text-text-muted">{title}</span>
            <span className="sa:truncate sa:text-sm sa:font-medium sa:text-text-default">{picked.join(' · ')}</span>
          </div>
          {onEdit && (
            <Button variant="tertiary" onClick={onEdit} className="sa:text-text-muted" aria-label={labels.changeItem(title)}>
              {labels.change}
            </Button>
          )}
        </div>
      </div>
    )
  }

  const own = children != null
  const empty =
    type === 'radio' ? !value : type === 'checkbox' || type === 'chips' ? asArray(value).length === 0 : false

  return (
    <div
      ref={(node: HTMLDivElement | null) => {
        cardRef.current = node
        if (typeof ref === 'function') ref(node)
        else if (ref) ref.current = node
      }}
      role="group"
      aria-labelledby={titleId}
      data-slot="decision-card"
      data-type={type}
      className={card}
      {...props}
    >
      <Header
        titleRef={titleRef}
        titleId={titleId}
        title={title}
        step={step}
        hint={hint}
        onPreviousStep={onPreviousStep}
        onNextStep={onNextStep}
        previousStepLabel={previousStepLabel}
        nextStepLabel={nextStepLabel}
      />
      <div className="sa:relative">
        <div ref={bodyRef}>
      {own && children}

      {!own && type === 'radio' && (
        <RadioGroup.Root
          aria-labelledby={titleId}
          value={typeof value === 'string' ? value : ''}
          onValueChange={set}
          className="sa:flex sa:flex-col sa:gap-0.5 sa:px-2"
        >
          {options.map((option) => (
            <DecisionItem key={option.value}>
              <RadioRow option={option} />
            </DecisionItem>
          ))}
        </RadioGroup.Root>
      )}

      {!own && type === 'checkbox' && (
        <div className="sa:flex sa:flex-col sa:gap-0.5 sa:px-2">
          {options.map((option) => {
            const checked = asArray(value).includes(option.value)
            return (
              <DecisionItem key={option.value}>
                <CheckboxRow
                  option={option}
                  checked={checked}
                  onCheckedChange={(on) => set(toggle(asArray(value), option.value, on))}
                />
              </DecisionItem>
            )
          })}
        </div>
      )}

      {!own && type === 'chips' && (
        <div className="sa:flex sa:flex-wrap sa:gap-1.5 sa:px-3 sa:pb-1">
          {options.map((option) => {
            const chosen = asArray(value)
            const selected = chosen.includes(option.value)
            const full = max !== undefined && chosen.length >= max && !selected
            return (
              <DecisionChip
                key={option.value}
                option={option}
                selected={selected}
                disabled={full}
                onPressedChange={(on) => set(toggle(chosen, option.value, on))}
              />
            )
          })}
        </div>
      )}

      {!own && type === 'ranking' && (
        <Ranking key={question} options={options} value={asArray(value)} onValueChange={set} labelledBy={titleId} />
      )}

      {!own && type === 'draft' && (
        <Draft
          key={question}
          title={draftTitle}
          value={typeof value === 'string' ? value : ''}
          onValueChange={set}
          onRewrite={onRewrite}
          onSkip={onSkip}
          onContinue={() => onContinue?.(value)}
          continueLabel={continueLabel ?? labels.useReply}
          skipLabel={skipLabel}
        />
      )}

        </div>
      </div>

      {type !== 'draft' && footer !== undefined && (
        <div ref={footerRef} className="sa:flex sa:items-center sa:justify-end sa:gap-2 sa:px-3 sa:pt-4 sa:pb-3">
          {footer}
        </div>
      )}
      {type !== 'draft' && footer === undefined && (
        <div ref={footerRef} className="sa:flex sa:items-center sa:justify-end sa:gap-2 sa:px-3 sa:pt-4 sa:pb-3">
          {onSkip && (
            <Button variant="tertiary" onClick={onSkip} className="sa:text-text-muted">
              {skipLabel}
            </Button>
          )}
          <Button onClick={() => onContinue?.(value)} disabled={empty}>
            {continueLabel ?? labels.continue}
          </Button>
        </div>
      )}
    </div>
  )
}

function Header({
  titleRef,
  titleId,
  title,
  step,
  hint,
  onPreviousStep,
  onNextStep,
  previousStepLabel,
  nextStepLabel,
}: {
  titleRef: React.Ref<HTMLDivElement>
  titleId: string
  title: string
  step?: string
  hint?: string
  onPreviousStep?: () => void
  onNextStep?: () => void
  previousStepLabel?: string
  nextStepLabel?: string
}) {
  const labels = useSatinLabels()
  return (
    <div className="sa:flex sa:items-start sa:gap-0.5 sa:py-3 sa:ps-3 sa:pe-px">
      {/* The title and hint move with the question; the step navigator stays. */}
      <div className="sa:relative sa:min-w-0 sa:flex-1">
        <div ref={titleRef} className="sa:flex sa:flex-col sa:gap-0.5">
          <p id={titleId} className="sa:text-base sa:leading-5 sa:font-medium sa:tracking-normal sa:text-text-default">
            {title}
          </p>
          {hint && <p className="sa:text-base sa:text-text-muted">{hint}</p>}
        </div>
      </div>
      {step && (
        <div className="sa:flex sa:h-[21px] sa:shrink-0 sa:items-center sa:gap-1 sa:pe-2">
          <Button
            variant="tertiary"
            size="xs"
            shape="rounded"
            iconOnly
            aria-label={previousStepLabel ?? labels.previousQuestion}
            disabled={!onPreviousStep}
            onClick={onPreviousStep}
          >
            {/* Mirrored right to left, where the previous question is to the right. */}
            <NavArrowLeft aria-hidden className="sa:rtl:-scale-x-100" />
          </Button>
          <StepCount step={step} />
          <Button
            variant="tertiary"
            size="xs"
            shape="rounded"
            iconOnly
            aria-label={nextStepLabel ?? labels.nextQuestion}
            disabled={!onNextStep}
            onClick={onNextStep}
          >
            <NavArrowRight aria-hidden className="sa:rtl:-scale-x-100" />
          </Button>
        </div>
      )}
    </div>
  )
}

// The controls a question's answers can take focus at. A radio group's root is left out: it only
// hands focus on to its items, which it hasn't registered yet when the question is new.
const TABBABLE = 'button:not(:disabled):not([tabindex="-1"]), input:not(:disabled):not([tabindex="-1"]), textarea:not(:disabled), [tabindex="0"]'

const STEP_MS = 360
const EASE = 'cubic-bezier(0.22, 1, 0.36, 1)'
const GAP = 24
const reducedMotion = () => typeof window !== 'undefined' && !!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches
const stepIndex = (step?: string) => (step ? parseInt(step, 10) || 0 : 0)

/**
 * Slides the parts in `refs` when `key` changes, as one horizontal track: a copy of how each part
 * looked and the part itself sit side by side, GAP apart, and move a card's width plus GAP to the
 * side together, the copy fading out and the part fading in, while the part's box (its parent)
 * eases from the old height to the new one and clips them. The direction comes from the "2/3"
 * step; without one it moves forward. A part that reads the same on both steps stays still.
 */
function useStepSlide(
  key: string,
  step: string | undefined,
  cardRef: React.RefObject<HTMLDivElement | null>,
  refs: React.RefObject<HTMLDivElement | null>[],
) {
  const last = React.useRef<{ key: string; index: number; heights: number[]; copies: (Node | null)[] } | null>(null)
  const index = stepIndex(step)

  React.useLayoutEffect(() => {
    const card = cardRef.current
    const prev = last.current

    if (card && prev && prev.key !== key && !reducedMotion()) {
      // The next question comes in from the end side: the right, or the left in right-to-left.
      const sign = (index < prev.index ? -1 : 1) * (getComputedStyle(card).direction === 'rtl' ? -1 : 1)
      const distance = card.clientWidth + GAP
      const timing: KeyframeAnimationOptions = { duration: STEP_MS, easing: EASE }
      refs.forEach((ref, i) => {
        const el = ref.current
        const host = el?.parentElement
        const copy = prev.copies[i] as HTMLElement | null
        if (!el || !host) return
        // The same on both steps (a title every step shares): it stays still.
        if (copy?.isEqualNode(el)) return
        // Stepping again mid-slide: everything goes on from where it is now, not from rest.
        const midway = el.getAnimations().length > 0
        const now = midway ? getComputedStyle(el) : null
        const start: Keyframe = {
          transform: now && now.transform !== 'none' ? now.transform : 'translate3d(0, 0, 0)',
          opacity: now ? Number(now.opacity) : 1,
        }
        const fromHeight = host.getAnimations().length > 0 ? host.getBoundingClientRect().height : prev.heights[i]
        for (const n of [el, host]) n.getAnimations().forEach((a) => a.cancel())
        host.querySelectorAll(':scope > [data-step-copy]').forEach((n) => n.remove())
        const toHeight = el.offsetHeight

        host.style.overflow = 'clip'
        const slide = el.animate(
          [{ transform: `translate3d(${sign * distance}px, 0, 0)`, opacity: 0 }, { transform: 'translate3d(0, 0, 0)', opacity: 1 }],
          timing,
        )
        if (Math.abs(fromHeight - toHeight) > 0.5) host.animate([{ height: `${fromHeight}px` }, { height: `${toHeight}px` }], timing)
        if (copy) {
          copy.setAttribute('data-step-copy', '')
          copy.setAttribute('aria-hidden', 'true')
          copy.setAttribute('inert', '')
          copy.querySelectorAll('[id]').forEach((n) => n.removeAttribute('id'))
          copy.style.cssText += ';position:absolute;top:0;left:0;right:0;pointer-events:none'
          host.appendChild(copy)
          copy.animate([start, { transform: `translate3d(${-sign * distance}px, 0, 0)`, opacity: 0 }], timing)
        }
        // Done: the copy goes and the box stops clipping. Cut short by another step: that one takes over.
        slide.finished.then(
          () => {
            copy?.remove()
            host.style.overflow = ''
          },
          () => {},
        )
      })
    }

    // Each part's own height, which no running animation changes.
    last.current = { key, index, heights: refs.map((r) => r.current?.offsetHeight ?? 0), copies: refs.map((r) => r.current?.cloneNode(true) ?? null) }
  })
}

const ROLL_MS = 350
const ROLL_EASE = 'cubic-bezier(0.4, 0, 0.2, 1)'

/**
 * The "1/3" count. Its changed digits roll like an odometer, in a box one line high: up going
 * forward, down going back. Screen readers get the plain count from a polite live region.
 */
function StepCount({ step }: { step: string }) {
  const last = React.useRef(step)
  const round = React.useRef(0)
  const [roll, setRoll] = React.useState<{ from: string; up: boolean; key: number } | null>(null)
  React.useLayoutEffect(() => {
    const from = last.current
    if (from === step) return
    last.current = step
    setRoll(reducedMotion() ? null : { from, up: stepIndex(step) >= stepIndex(from), key: ++round.current })
  }, [step])

  // Right-aligned, so units stay over units when a digit is gained or lost.
  const width = Math.max(step.length, roll?.from.length ?? 0)
  const to = step.padStart(width, ' ')
  const from = (roll?.from ?? step).padStart(width, ' ')
  const cell = (ch: string) => (ch === ' ' ? '' : ch)
  return (
    <span className="sa:text-sm sa:whitespace-nowrap sa:text-text-muted sa:tabular-nums">
      <span aria-live="polite" className="sa:sr-only">
        {step}
      </span>
      <span aria-hidden className="sa:inline-flex">
        {[...to].map((ch, i) =>
          roll && from[i] !== ch ? (
            <span key={`${roll.key}-${i}`} className="sa:inline-flex sa:h-lh sa:flex-col sa:overflow-hidden">
              <span
                className="sa:flex sa:flex-col"
                ref={(column) => {
                  if (!column || column.dataset.rolled) return
                  column.dataset.rolled = ''
                  const end = roll.up ? 'translateY(-50%)' : 'translateY(0)'
                  column
                    .animate([{ transform: roll.up ? 'translateY(0)' : 'translateY(-50%)' }, { transform: end }], { duration: ROLL_MS, easing: ROLL_EASE })
                    .finished.then(
                      () => setRoll((r) => (r?.key === roll.key ? null : r)),
                      () => {},
                    )
                }}
              >
                <span className="sa:h-lh">{cell(roll.up ? from[i] : ch)}</span>
                <span className="sa:h-lh">{cell(roll.up ? ch : from[i])}</span>
              </span>
            </span>
          ) : ch === ' ' ? null : (
            <span key={i}>{ch}</span>
          ),
        )}
      </span>
    </span>
  )
}

/** `decisionItem` (3092:61608): 4px padding, radius-md, action/secondary fill on hover. */
function DecisionItem({ children, 'data-force': force }: { children: React.ReactNode; 'data-force'?: 'hover' }) {
  return (
    <div
      data-force={force}
      className="sa:rounded-md sa:p-1 sa:transition-[background-color] sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out) sa:satin-hover:bg-action-secondary-bg"
    >
      {children}
    </div>
  )
}

function RadioRow({ option }: { option: DecisionOption }) {
  const id = React.useId()
  return (
    <div className="sa:flex sa:h-5 sa:items-center sa:gap-2">
      <RadioGroup.Item
        id={id}
        value={option.value}
        className={cn(
          'sa:flex sa:size-4 sa:shrink-0 sa:items-center sa:justify-center sa:rounded-full sa:border sa:border-border-strong sa:bg-bg-field sa:outline-none',
          'sa:[box-shadow:0_1px_2px_0_var(--sa-effect-shadow-xs)]',
          'sa:transition-[background-color,border-color,box-shadow] sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)',
          'sa:data-[state=checked]:border-action-primary-bg sa:data-[state=checked]:bg-action-primary-bg sa:data-[state=checked]:[box-shadow:none]',
          'sa:focus-visible:[box-shadow:0_0_0_2px_var(--sa-action-focus-ring)] sa:data-[state=checked]:focus-visible:[box-shadow:0_0_0_2px_var(--sa-action-focus-ring)]',
        )}
      >
        <RadioGroup.Indicator className="sa:size-1.5 sa:rounded-full sa:bg-text-on-solid" />
      </RadioGroup.Item>
      <label htmlFor={id} className="sa:min-w-0 sa:flex-1 sa:text-base sa:text-text-default">
        {option.label}
      </label>
    </div>
  )
}

function CheckboxRow({
  option,
  checked,
  onCheckedChange,
}: {
  option: DecisionOption
  checked: boolean
  onCheckedChange: (checked: boolean) => void
}) {
  const id = React.useId()
  return (
    <div className="sa:flex sa:h-5 sa:items-center sa:gap-2">
      <Checkbox id={id} checked={checked} onCheckedChange={(c) => onCheckedChange(c === true)} />
      <label htmlFor={id} className="sa:min-w-0 sa:flex-1 sa:text-base sa:text-text-default">
        {option.label}
      </label>
    </div>
  )
}

function DecisionChip({
  option,
  selected,
  disabled,
  onPressedChange,
}: {
  option: DecisionOption
  selected: boolean
  disabled?: boolean
  onPressedChange: (pressed: boolean) => void
}) {
  return (
    <button
      type="button"
      aria-pressed={selected}
      disabled={disabled}
      onClick={() => onPressedChange(!selected)}
      className={cn(
        'sa:inline-flex sa:h-control-height sa:shrink-0 sa:items-center sa:gap-1.5 sa:rounded-pill sa:border sa:ps-2 sa:pe-2.5 sa:text-base sa:font-medium sa:outline-none sa:select-none',
