function Ranking({
  options,
  value,
  onValueChange,
  labelledBy,
}: {
  options: DecisionOption[]
  value: string[]
  onValueChange: (value: string[]) => void
  labelledBy: string
}) {
  const labels = useSatinLabels()
  const order = value.length ? value : options.map((o) => o.value)
  const [dragging, setDragging] = React.useState<string | null>(null)
  const [announcement, setAnnouncement] = React.useState('')
  const listRef = React.useRef<HTMLOListElement>(null)
  const label = (v: string) => options.find((o) => o.value === v)?.label ?? v

  const move = (from: number, to: number) => {
    if (to < 0 || to >= order.length || from === to) return
    const next = [...order]
    const [item] = next.splice(from, 1)
    next.splice(to, 0, item)
    onValueChange(next)
    return next
  }

  const onPointerDown = (e: React.PointerEvent<HTMLLIElement>, item: string) => {
    if (e.button !== 0) return
    e.currentTarget.setPointerCapture(e.pointerId)
    setDragging(item)
  }
  const onPointerMove = (e: React.PointerEvent<HTMLLIElement>) => {
    if (!dragging || !listRef.current) return
    const rows = Array.from(listRef.current.children) as HTMLElement[]
    const from = order.indexOf(dragging)
    let to = from
    rows.forEach((row, i) => {
      const box = row.getBoundingClientRect()
      const mid = box.top + box.height / 2
      if (i < from && e.clientY < mid) to = Math.min(to, i)
      if (i > from && e.clientY > mid) to = Math.max(to, i)
    })
    if (to !== from) move(from, to)
  }
  const onPointerUp = () => {
    if (dragging) setAnnouncement(labels.positionOf(label(dragging), order.indexOf(dragging) + 1, order.length))
    setDragging(null)
  }

  const onKeyDown = (e: React.KeyboardEvent<HTMLLIElement>, index: number) => {
    if (e.key !== 'ArrowUp' && e.key !== 'ArrowDown') return
    e.preventDefault()
    const to = index + (e.key === 'ArrowUp' ? -1 : 1)
    if (e.altKey) {
      const next = move(index, to)
      if (next) {
        setAnnouncement(labels.positionOf(label(next[to]), to + 1, next.length))
        requestAnimationFrame(() => (listRef.current?.children[to] as HTMLElement | undefined)?.focus())
      }
    } else {
      ;(listRef.current?.children[to] as HTMLElement | undefined)?.focus()
    }
  }

  return (
    <div className="sa:px-3 sa:pb-1">
      <ol ref={listRef} aria-labelledby={labelledBy} className="sa:flex sa:flex-col sa:gap-1.5">
        {order.map((item, i) => {
          const lifted = dragging === item
          return (
            <li
              key={item}
              tabIndex={0}
              aria-roledescription={labels.sortableItem}
              aria-description={labels.sortableHint}
              data-dragging={lifted || undefined}
              onPointerDown={(e) => onPointerDown(e, item)}
              onPointerMove={onPointerMove}
              onPointerUp={onPointerUp}
              onPointerCancel={onPointerUp}
              onKeyDown={(e) => onKeyDown(e, i)}
              className={cn(
                'sa:group/rank sa:flex sa:cursor-grab sa:touch-none sa:items-center sa:gap-2 sa:rounded-lg sa:border sa:border-border-default sa:bg-bg-popover sa:py-2 sa:ps-2 sa:pe-2.5 sa:outline-none sa:select-none',
                'sa:transition-[border-color,box-shadow] sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)',
                'sa:hover:border-border-strong sa:focus-visible:[box-shadow:0_0_0_2px_var(--sa-action-focus-ring)]',
                'sa:data-dragging:cursor-grabbing sa:data-dragging:border-border-strong',
                'sa:data-dragging:[box-shadow:0_4px_6px_-1px_var(--sa-effect-shadow-sm),0_2px_4px_-2px_var(--sa-effect-shadow-sm)]',
              )}
            >
              <Grip />
              <span
                className={cn(
                  'sa:flex sa:size-5 sa:shrink-0 sa:items-center sa:justify-center sa:rounded-full sa:text-xs sa:tabular-nums',
                  i === 0 ? 'sa:bg-action-primary-bg sa:text-action-primary-fg' : 'sa:bg-bg-muted sa:text-text-muted',
                )}
              >
                {i + 1}
              </span>
              <span className="sa:min-w-0 sa:flex-1 sa:text-base sa:font-medium sa:text-text-default">{label(item)}</span>
            </li>
          )
        })}
      </ol>
      <span aria-live="polite" className="sa:sr-only">
        {announcement}
      </span>
    </div>
  )
}

/** The 8 × 14 six-dot grip from Figma: text/subtle at rest, text/muted while dragging. */
function Grip() {
  return (
    <svg
      width="8"
      height="14"
      viewBox="0 0 8 14"
      aria-hidden
      className="sa:shrink-0 sa:fill-current sa:text-text-subtle sa:group-data-dragging/rank:text-text-muted"
    >
      {[1.25, 6.75, 12.25].map((cy) => (
        <React.Fragment key={cy}>
          <circle cx="1.25" cy={cy} r="1.25" />
          <circle cx="6.25" cy={cy} r="1.25" />
        </React.Fragment>
      ))}
    </svg>
  )
}

function Draft({
  title,
  value,
  onValueChange,
  onRewrite,
  onSkip,
  onContinue,
  continueLabel,
  skipLabel,
}: {
  title?: string
  value: string
  onValueChange: (value: string) => void
  onRewrite?: () => void
  onSkip?: () => void
  onContinue: () => void
  continueLabel: string
  skipLabel: string
}) {
  const labels = useSatinLabels()
  const [editing, setEditing] = React.useState(false)
  const areaRef = React.useRef<HTMLTextAreaElement>(null)

  React.useLayoutEffect(() => {
    const el = areaRef.current
    if (!el) return
    el.style.height = '0px'
    el.style.height = `${el.scrollHeight}px`
  }, [value, editing])

  return (
    <>
      <div className="sa:px-3 sa:pb-1">
        <div
          className={cn(
            'sa:flex sa:flex-col sa:gap-2 sa:rounded-2xl sa:rounded-ss-[4px] sa:border sa:border-border-default sa:bg-bg-popover sa:px-3 sa:py-2.5 sa:text-base sa:text-text-default',
            'sa:[box-shadow:0_1px_2px_0_var(--sa-effect-shadow-xs)]',
            'sa:transition-[box-shadow,border-color] sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)',
            'sa:has-[textarea:focus-visible]:border-border-focus sa:has-[textarea:focus-visible]:[box-shadow:0_0_0_1px_var(--sa-border-focus)]',
          )}
        >
          {title && <p className="sa:leading-[18px] sa:font-medium">{title}</p>}
          {editing ? (
            <textarea
              ref={areaRef}
              aria-label={labels.draft}
              value={value}
              onChange={(e) => onValueChange(e.target.value)}
              className="sa:w-full sa:resize-none sa:bg-transparent sa:outline-none"
            />
          ) : (
            <p className="sa:whitespace-pre-wrap">{value}</p>
          )}
        </div>
      </div>
      <div className="sa:flex sa:items-center sa:justify-between sa:gap-2 sa:px-3 sa:pt-4 sa:pb-3">
        <Button
          variant="tertiary"
          className="sa:text-text-muted"
          aria-pressed={editing}
          onClick={() => {
            setEditing(true)
            requestAnimationFrame(() => areaRef.current?.focus())
            onRewrite?.()
          }}
        >
          <EditPencil aria-hidden />
          {labels.rewrite}
        </Button>
        <div className="sa:flex sa:items-center sa:gap-2">
          {onSkip && (
            <Button variant="tertiary" onClick={onSkip} className="sa:text-text-muted">
              {skipLabel}
            </Button>
          )}
          <Button onClick={onContinue} disabled={!value.trim()}>
            {continueLabel}
          </Button>
        </div>
      </div>
    </>
  )
}

/** A static `decisionItem` row in its hover state, for state sheets. */
export function DecisionItemPreview({ children, hover }: { children: React.ReactNode; hover?: boolean }) {
  return <DecisionItem data-force={hover ? 'hover' : undefined}>{children}</DecisionItem>
}

function initialValue(type: DecisionCardProps['type'], options: DecisionOption[]): DecisionValue {
  if (type === 'ranking') return options.map((o) => o.value)
  if (type === 'radio' || type === 'draft') return ''
  return []
}

function asArray(value: DecisionValue | undefined): string[] {
  if (Array.isArray(value)) return value
  return value ? [value] : []
}

function toggle(list: string[], item: string, on: boolean) {
  return on ? (list.includes(item) ? list : [...list, item]) : list.filter((v) => v !== item)
}
